          const icon = link.label.toLowerCase() === "today" ? "today" : link.label.toLowerCase();
          return <Link key={link.href} href={link.href} onClick={() => setMobileOpen(false)} aria-current={active ? "page" : undefined} className={`flex min-h-9 items-center gap-3 rounded-md px-3 text-[13px] font-medium transition-colors ${active ? "bg-neutral-200 text-neutral-950" : "text-neutral-600 hover:bg-neutral-100 hover:text-neutral-950"}`}><Icon name={icon} className="size-4 shrink-0" />{link.label}</Link>;
        })}</div>
      </section>)}
    </nav>
    <div className="border-t border-neutral-200 p-2"><a href={`/${tenant}`} target="_blank" rel="noreferrer" className="flex min-h-9 items-center gap-3 rounded-md px-3 text-[13px] font-medium text-neutral-600 hover:bg-neutral-100 hover:text-neutral-950"><Icon name="external" className="size-4" />Public site</a></div>
  </>;

  return <div className="flex min-h-[calc(100vh-2.5rem)]">
    <aside className="sticky top-0 hidden h-screen w-60 shrink-0 flex-col border-r border-neutral-200 bg-white md:flex">{sidebar}</aside>
    <div className="flex min-w-0 flex-1 flex-col">
