        </div>
        <nav aria-label="Account" className="flex items-center gap-0.5">
          <button type="button" onClick={toggleTheme} aria-label={`Switch to ${theme === "light" ? "dark" : "light"} mode`} title={`Switch to ${theme === "light" ? "dark" : "light"} mode`} className="grid size-8 place-items-center rounded-md text-neutral-600 hover:bg-neutral-100"><Icon name={theme === "light" ? "moon" : "sun"} className="size-4" /></button>
