    routine: Array.isArray(raw.routine) ? raw.routine : [],
    weeklyOverrides: raw.weeklyOverrides && typeof raw.weeklyOverrides === "object" ? raw.weeklyOverrides : {},
    dateOverrides: Array.isArray(raw.dateOverrides) ? raw.dateOverrides : [],
  };
}

